// Service Worker — auto-generated by PWA 打包神器
// Cache key: 奇門遁甲自動對位-v8
// Strategy: Network-First (HTML) + Cache-First (assets)

const CACHE_NAME = '奇門遁甲自動對位-v8';
const PRECACHE_URLS = [
    "/cheman/index.html",
    "/cheman/sw.js",
    "/cheman/manifest.json",
    "/cheman/icon.svg",
    "/cheman/offline.html",
    "/cheman/icon-192.png",
    "/cheman/icon-512.png",
    "https://cdn.jsdelivr.net/npm/lunar-javascript@1.7.7/lunar.js"
];

// Install: pre-cache assets
self.addEventListener('install', event => {
  event.waitUntil(
    caches.open(CACHE_NAME).then(cache => {
      return cache.addAll(PRECACHE_URLS).catch(err => {
        console.warn('[SW] Pre-cache partial failure:', err);
      });
    }).then(() => self.skipWaiting())
  );
});

// Activate: clean old caches
self.addEventListener('activate', event => {
  event.waitUntil(
    caches.keys().then(keys =>
      Promise.all(
        keys.filter(k => k !== CACHE_NAME)
            .map(k => caches.delete(k))
      )
    ).then(() => self.clients.claim())
  );
});

// Fetch strategy:
//   HTML documents → Network-First（先拿最新，離線用快取）
//   其他資源      → Cache-First（快取優先，離線可用）
self.addEventListener('fetch', event => {
  if (event.request.method !== 'GET') return;
  const url = new URL(event.request.url);
  if (url.protocol === 'chrome-extension:') return;

  const isDocument = event.request.destination === 'document' ||
                     event.request.headers.get('accept')?.includes('text/html');

  if (isDocument) {
    // Network-First for HTML：有網路一律拿最新版，離線才用快取
    event.respondWith(
      fetch(event.request).then(response => {
        if (response && response.status === 200) {
          const copy = response.clone();
          caches.open(CACHE_NAME).then(cache => cache.put(event.request, copy));
        }
        return response;
      }).catch(() =>
        caches.match(event.request).then(c => c || caches.match('/cheman/offline.html'))
      )
    );
  } else {
    // Cache-First for assets
    event.respondWith(
      caches.match(event.request).then(cached => {
        if (cached) return cached;
        return fetch(event.request).then(response => {
          if (!response || response.status !== 200 || response.type === 'opaque') {
            return response;
          }
          const cloned = response.clone();
          caches.open(CACHE_NAME).then(cache => cache.put(event.request, cloned));
          return response;
        }).catch(() => {
          if (event.request.destination === 'document') {
            return caches.match('/cheman/offline.html');
          }
        });
      })
    );
  }
});
